package com.yeyamo_mobile.api.notification_service.infrastructure.messaging;
import java.util.UUID;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;import com.fasterxml.jackson.databind.*;import com.yeyamo_mobile.api.notification_service.application.NotificationApplicationService;
@Component public class NotificationEventConsumer{private final ObjectMapper mapper;private final EventNotificationPolicy policy;private final NotificationApplicationService service;private final ProcessedEventRepository processed;public NotificationEventConsumer(ObjectMapper m,EventNotificationPolicy p,NotificationApplicationService s,ProcessedEventRepository r){mapper=m;policy=p;service=s;processed=r;}@KafkaListener(topics={"${yeyamo.kafka.topics.auth-events:auth.events}","${yeyamo.kafka.topics.partner-events:partner-events}","${yeyamo.kafka.topics.moderation-events:moderation.events}","${yeyamo.kafka.topics.messaging-events:messaging.events}"},groupId="${spring.kafka.consumer.group-id:notification-service}")@Transactional public void consume(String raw)throws Exception{JsonNode event=mapper.readTree(raw);UUID id=UUID.fromString(required(event,"eventId"));if(processed.existsById(id))return;String type=required(event,"eventType");for(var intent:policy.map(event))service.create(intent);processed.save(new ProcessedEventEntity(id,type));}private String required(JsonNode n,String f){JsonNode v=n.get(f);if(v==null||v.isNull()||v.asText().isBlank())throw new IllegalArgumentException(f+" is required");return v.asText();}}
